# test_orders.py - pytest + TestClient + dependency override
import pytest
from fastapi import FastAPI, Depends, HTTPException
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()

class OrderIn(BaseModel):
    sku: str
    qty: int

def get_repo():
    raise RuntimeError("real DB not available in tests")

@app.post("/orders", status_code=201)
def create_order(order: OrderIn, repo=Depends(get_repo)):
    if order.qty <= 0:
        raise HTTPException(422, "qty must be positive")
    return repo.save(order)

class FakeRepo:
    def save(self, order): return {"id": 1, **order.model_dump()}

@pytest.fixture
def client():
    app.dependency_overrides[get_repo] = lambda: FakeRepo()
    yield TestClient(app)
    app.dependency_overrides.clear()

@pytest.mark.parametrize("payload,status", [
    ({"sku": "PEN", "qty": 2}, 201),
    ({"sku": "PEN", "qty": "x"}, 422),       # Pydantic validation
    ({"sku": "PEN"}, 422),                    # missing field
])
def test_create_order(client, payload, status):
    assert client.post("/orders", json=payload).status_code == status
