# Mocking an outgoing HTTP call with httpx.MockTransport
import httpx

def handler(request: httpx.Request) -> httpx.Response:
    return httpx.Response(200, json={"price": 9.99})

def fetch_price(client: httpx.Client, sku: str) -> float:
    return client.get(f"https://pricing.example.com/{sku}").json()["price"]

def test_fetch_price():
    client = httpx.Client(transport=httpx.MockTransport(handler))
    assert fetch_price(client, "PEN") == 9.99
